import{_ as t,o as i,c as a,a0 as n}from"./chunks/framework.DB31oXgM.js";const h=JSON.parse('{"title":"02 - Requirements Specification: Rollback Netcode Server","description":"","frontmatter":{},"headers":[],"relativePath":"02-requirements.md","filePath":"02-requirements.md"}'),r={name:"02-requirements.md"};function o(s,e,l,c,u,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_02-requirements-specification-rollback-netcode-server" tabindex="-1">02 - Requirements Specification: Rollback Netcode Server <a class="header-anchor" href="#_02-requirements-specification-rollback-netcode-server" aria-label="Permalink to &quot;02 - Requirements Specification: Rollback Netcode Server&quot;">​</a></h1><h2 id="_1-functional-requirements-fr-specified" tabindex="-1">1. Functional Requirements (FR) [Specified] <a class="header-anchor" href="#_1-functional-requirements-fr-specified" aria-label="Permalink to &quot;1. Functional Requirements (FR) [Specified]&quot;">​</a></h2><h3 id="_1-1-deterministic-simulation-engine" tabindex="-1">1.1 Deterministic Simulation Engine <a class="header-anchor" href="#_1-1-deterministic-simulation-engine" aria-label="Permalink to &quot;1.1 Deterministic Simulation Engine&quot;">​</a></h3><ul><li><strong>FR-001</strong>: The engine MUST execute all physics, kinematics, and bounding-box collision math using 32-bit fixed-point arithmetic (<code>FixedI32</code> with 16-bit fractional precision).</li><li><strong>FR-002</strong>: The engine MUST maintain a strictly seeded Pseudo-Random Number Generator (PRNG using PCG32 or SplitMix64) that steps deterministically with each frame tick.</li><li><strong>FR-003</strong>: Entity updates MUST execute in an absolute, stable iteration order sorted by unique 32-bit Entity ID.</li><li><strong>FR-004</strong>: The engine MUST support serialization and deserialization of the entire <code>WorldState</code> struct to and from canonical byte buffers without heap allocations.</li></ul><h3 id="_1-2-snapshot-storage-ring-buffer" tabindex="-1">1.2 Snapshot Storage &amp; Ring Buffer <a class="header-anchor" href="#_1-2-snapshot-storage-ring-buffer" aria-label="Permalink to &quot;1.2 Snapshot Storage &amp; Ring Buffer&quot;">​</a></h3><ul><li><strong>FR-005</strong>: The system MUST allocate a fixed-capacity circular ring buffer capable of holding at least 128 consecutive historical <code>WorldState</code> snapshots and their associated Blake3 64-bit checksums.</li><li><strong>FR-006</strong>: Ring buffer indexing MUST be $O(1)$ and lockless or use low-contention atomic sequence numbers.</li><li><strong>FR-007</strong>: State lookups for any frame $F$ where $(F_{current} - 128) \\le F \\le F_{current}$ MUST return the exact immutable snapshot recorded at frame $F$.</li></ul><h3 id="_1-3-rollback-resimulation" tabindex="-1">1.3 Rollback &amp; Resimulation <a class="header-anchor" href="#_1-3-rollback-resimulation" aria-label="Permalink to &quot;1.3 Rollback &amp; Resimulation&quot;">​</a></h3><ul><li><strong>FR-008</strong>: When a remote input packet for frame $F_{remote}$ arrives where $F_{remote} &lt; F_{current}$, the engine MUST rewind its active state to $F_{remote}$, inject the newly confirmed remote input, and resimulate every tick forward up to $F_{current}$.</li><li><strong>FR-009</strong>: If multiple remote inputs arrive simultaneously out of order, resimulation MUST occur from the earliest unconfirmed frame $\\min(F_{remote})$ in a single contiguous batch.</li><li><strong>FR-010</strong>: During rollback resimulation, audio triggers, visual particle spawns, and non-stateful events MUST be masked to prevent duplicate sensory artifacts.</li></ul><h3 id="_1-4-network-protocol-clock-sync" tabindex="-1">1.4 Network Protocol &amp; Clock Sync <a class="header-anchor" href="#_1-4-network-protocol-clock-sync" aria-label="Permalink to &quot;1.4 Network Protocol &amp; Clock Sync&quot;">​</a></h3><ul><li><strong>FR-011</strong>: UDP datagrams MUST bundle the current frame&#39;s input bitmask along with the preceding 4 historical frames ($F-1, F-2, F-3, F-4$) to provide resilient input transmission over lossy networks.</li><li><strong>FR-012</strong>: The client and server MUST exchange high-resolution NTP-style ping/pong packets every 500 ms to compute Round-Trip Time (RTT), clock offset $ heta$, and network jitter $\\sigma$.</li><li><strong>FR-013</strong>: The client MUST dynamically adjust its local clock speed by $\\pm 1%$ to seamlessly synchronize its simulation frame timeline with the server authority.</li></ul><h3 id="_1-5-desync-detection-telemetry" tabindex="-1">1.5 Desync Detection &amp; Telemetry <a class="header-anchor" href="#_1-5-desync-detection-telemetry" aria-label="Permalink to &quot;1.5 Desync Detection &amp; Telemetry&quot;">​</a></h3><ul><li><strong>FR-014</strong>: The client MUST compute a 64-bit Blake3 hash of its <code>WorldState</code> on every confirmed frame and transmit it to the server.</li><li><strong>FR-015</strong>: When a hash mismatch occurs between client and server for frame $F$, the server MUST flag a <code>DesyncIncident</code>, log the divergence, and snapshot both states for forensic diffing.</li></ul><h3 id="_1-6-artificial-intelligence-machine-learning-aiml" tabindex="-1">1.6 Artificial Intelligence &amp; Machine Learning (AIML) <a class="header-anchor" href="#_1-6-artificial-intelligence-machine-learning-aiml" aria-label="Permalink to &quot;1.6 Artificial Intelligence &amp; Machine Learning (AIML)&quot;">​</a></h3><ul><li><strong>FR-016 (Tier A)</strong>: The system MUST execute an unsupervised Isolation Forest anomaly detection model on sliding 60-frame input feature vectors to flag macro usage and aimbot inputs.</li><li><strong>FR-017 (Tier A)</strong>: The system MUST evaluate an Adaptive Kalman Filter on network jitter timeseries to predict upcoming jitter spikes and dynamically adjust client input delay.</li><li><strong>FR-018 (Tier B)</strong>: The system MUST provide an LLM-assisted endpoint (<code>/api/v1/ai/explain-desync</code>) that receives binary state diffs and outputs structured JSON containing root-cause analysis, affected entities, and remediation recommendations.</li><li><strong>FR-019</strong>: All AIML modules MUST support graceful degradation: if AI services are offline or disabled, the server MUST revert to hardcoded static threshold rule engines with zero interruption to active gameplay.</li></ul><hr><h2 id="_2-non-functional-requirements-nfr-specified" tabindex="-1">2. Non-Functional Requirements (NFR) [Specified] <a class="header-anchor" href="#_2-non-functional-requirements-nfr-specified" aria-label="Permalink to &quot;2. Non-Functional Requirements (NFR) [Specified]&quot;">​</a></h2><h3 id="_2-1-performance-latency" tabindex="-1">2.1 Performance &amp; Latency <a class="header-anchor" href="#_2-1-performance-latency" aria-label="Permalink to &quot;2.1 Performance &amp; Latency&quot;">​</a></h3><ul><li><strong>NFR-001</strong>: Single-frame deterministic simulation step duration MUST be under 50 microseconds for an arena containing 64 dynamic entities on a single CPU core.</li><li><strong>NFR-002</strong>: UDP packet processing overhead on the server MUST not exceed 500 microseconds per client tick under a load of 1,000 concurrent active sessions.</li><li><strong>NFR-003</strong>: Telemetry ingestion pipeline MUST handle up to 50,000 input events per second with $p99$ persistence latency under 10 ms into PostgreSQL.</li></ul><h3 id="_2-2-reliability-availability" tabindex="-1">2.2 Reliability &amp; Availability <a class="header-anchor" href="#_2-2-reliability-availability" aria-label="Permalink to &quot;2.2 Reliability &amp; Availability&quot;">​</a></h3><ul><li><strong>NFR-004</strong>: Zero panic tolerance: no malformed UDP datagram, invalid bitmask, or corrupted client checksum may crash the server process.</li><li><strong>NFR-005</strong>: The server MUST gracefully disconnect unreachable clients after 3.0 seconds of contiguous packet loss without deadlocking the match room.</li></ul><h3 id="_2-3-security-integrity" tabindex="-1">2.3 Security &amp; Integrity <a class="header-anchor" href="#_2-3-security-integrity" aria-label="Permalink to &quot;2.3 Security &amp; Integrity&quot;">​</a></h3><ul><li><strong>NFR-006</strong>: The server MUST validate all client inputs against maximum feasible acceleration vectors (e.g. max velocity $\\le 10.0$ units/tick) prior to admitting inputs to the authoritative ring buffer.</li><li><strong>NFR-007</strong>: Matchmaking and telemetry REST APIs MUST authenticate clients via cryptographically signed JWT tokens (RS256 or HS256).</li></ul>',22)])])}const g=t(r,[["render",o]]);export{h as __pageData,g as default};
